cat >> /etc/nginx/nginx.conf << 'EOF'

        ## Custom Log Format ##
        log_format benchmark_log '$time_local $request_method $status "$http_user_agent"';

        ## Rate Limiting ##
        limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;
EOF

cat > /etc/nginx/conf.d/benchmark-site.conf << 'EOF'
server {
    listen 8080;
    server_name localhost;

    root /var/www/html;
    index index.html;

    # Custom access and error logging
    access_log /var/log/nginx/benchmark-access.log benchmark_log;
    error_log /var/log/nginx/benchmark-error.log;

    # Rate limiting
    limit_req zone=benchmark_limit burst=10;

    # Custom 404 error page
    error_page 404 /404.html;
    location = /404.html {
        internal;
    }

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF

